[{"order":1,"type":"heading","text":"Advanced Smart Contract Architecture: Factory, Proxy, and Upgradeability Patterns in Solidity"},{"order":2,"type":"paragraph","text":"As decentralized applications mature, the need for scalable, gas-efficient, and maintainable smart contract architectures becomes paramount. In this tutorial, we explore three foundational design patterns in Solidity: the Factory pattern for dynamic contract deployment, the Proxy pattern for decoupling state from logic, and Upgradeability patterns for future-proofing your decentralized protocols."},{"order":3,"type":"subheading","text":"1. The Factory Pattern"},{"order":4,"type":"paragraph","text":"The Factory pattern is used when a contract needs to create multiple instances of another contract. Instead of manually deploying contracts, a factory contract automates this process, maintaining a registry of all deployed instances."},{"order":5,"type":"code","text":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract ManagedAsset {
    address public owner;
    uint public createdAt;

    constructor(address _owner) {
        owner = _owner;
        createdAt = block.timestamp;
    }
}

contract AssetFactory {
    address[] public deployedAssets;

    event AssetCreated(address indexed assetAddress, address indexed owner);

    function createAsset() external {
        ManagedAsset newAsset = new ManagedAsset(msg.sender);
        deployedAssets.push(address(newAsset));
        emit AssetCreated(address(newAsset), msg.sender);
    }

    function getDeployedAssets() external view returns (address[] memory) {
        return deployedAssets;
    }
}"},{"order":6,"type":"subheading","text":"2. The Proxy Pattern"},{"order":7,"type":"paragraph","text":"Smart contracts on Ethereum are immutable. The Proxy pattern solves this by separating the interface and data storage (Proxy contract) from the business logic (Implementation contract). The proxy forwards all calls using the low-level assembly command delegatecall, which executes the implementation logic in the context of the proxy's storage."},{"order":8,"type":"code","text":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Proxy {
    address public implementation;
    address public admin;

    constructor(address _implementation) {
        implementation = _implementation;
        admin = msg.sender;
    }

    function upgradeTo(address _newImplementation) external {
        require(msg.sender == admin, "Not authorized");
        implementation = _newImplementation;
    }

    fallback() external payable {
        address impl = implementation;
        require(impl != address(0), "Implementation not set");

        assembly {
            calldatacopy(0, 0, calldatasize())
            let result := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch result
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }

    receive() external payable {}
}"},{"order":9,"type":"subheading","text":"3. Upgradeability and Storage Layout Safety"},{"order":10,"type":"paragraph","text":"When implementing upgradeable contracts, storage collisions are the most critical vulnerability. Because delegatecall alters the state of the proxy contract, any update to the implementation contract must strictly preserve the existing storage layout order."},{"order":11,"type":"bullet_point","text":"Never change the order or data types of existing state variables in newer implementation versions."},{"order":12,"type":"bullet_point","text":"Append new state variables strictly at the end of the contract inheritance tree."},{"order":13,"type":"bullet_point","text":"Use initializer functions instead of constructors, because constructors run once during implementation deployment and do not affect proxy storage."},{"order":14,"type":"code","text":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract ImplementationV1 {
    uint256 public value;

    function setValue(uint256 _value) public {
        value = _value;
    }
}

contract ImplementationV2 is ImplementationV1 {
    // Safe: Appended at the end
    uint256 public multiplier;

    function setMultiplier(uint256 _multiplier) public {
        multiplier = _multiplier;
    }

    function getCalculatedValue() public view returns (uint256) {
        return value * multiplier;
    }
}"},{"order":15,"type":"subheading","text":"Conclusion"},{"order":16,"type":"paragraph","text":"Combining Factories, Proxies, and Upgradeability patterns allows developers to build robust ecosystems capable of dynamic scaling and continuous improvement. Always conduct thorough audits and test storage layouts using framework plugins like OpenZeppelin Upgrades to secure production-grade decentralized applications."}]
